# Product-first page composition; shared helpers supplied by build.py.
cta='<a class="button" href="https://app.todoer.pro">Create your account ↗</a>'
def faq(items):return ''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)
def agent_story():return '<div class="agent-story"><div class="agent-copy"><p class="eyebrow">THINK IT THROUGH. THEN FOLLOW THROUGH.</p><h2>From chat<br>to checked off.</h2><p>Give the next steps from your AI conversation a home in Todoer.</p><ul class="agent-benefits"><li>Capture an idea</li><li>Find an existing task</li><li>Update the next step</li></ul><a class="secondary" href="/agents.html">Connect your workflow →</a></div><div class="chat-demo"><span class="pill">Illustrative agent workflow</span><p class="chat-user">“Turn this launch plan into tasks in my Todoer inbox.”</p><div class="chat-reply"><span class="accent">Ready for your next step.</span><ul><li>Draft the announcement</li><li>Review the landing page</li><li>Prepare the launch checklist</li></ul></div><p class="fine">Compatible client and authorization required. <a href="/agents.html">Connection details →</a></p></div></div>'

preview=re.search(r'(<section id="preview".*?</section>)',pages['index'][2],re.S).group(1)
pages['index']=('A clearer head. A next step you can take.','Get tasks out of your head and into motion. Todoer connects everyday planning with optional AI-agent workflows.', '<section class="hero wrap"><p class="eyebrow">FOR EVERYTHING YOU KEEP MEANING TO DO</p><h1>A clearer head.<br><span>A real next step.</span></h1><p class="lead">The project. The small errand. That idea from your AI chat.<br>Get it out of your head, give it a place, and move it forward.</p><div class="actions">'+cta+'<a class="secondary" href="#story">Find your breathing room ↓</a></div><p class="fine">Your tasks, your pace. AI when you want it.</p></section>'+section('Less in your head.<br>More within reach.','<div id="story" class="thought-flow"><div class="thought-cloud"><span>The idea from that chat</span><span>The thing for tomorrow</span><span>That project you keep putting off</span></div><span class="flow-arrow" aria-hidden="true">→</span><div class="next-step"><span class="eyebrow">ONE PLACE. ONE NEXT STEP.</span><p>Pick it up.<br>Move it forward.</p><a href="/product.html">Meet your new workspace →</a></div></div>')+preview+section('Being organized can feel<br>lighter than this.',cards([('Catch the thought','Save it before it slips away. You can organize it later.'),('Make the next step obvious','Break a daunting project into small tasks, with the context right beside them.'),('Leave the day with less unfinished','See what matters today. Let the rest wait somewhere you can trust yourself to check.')]))+section('Keep the momentum<br>after the conversation.',agent_story())+section('You already know how to begin.',cards([('One inbox','Put the scattered thoughts in one place. A rough sentence is enough.'),('One small action','Pick something you can finish. Add the context you need, skip the ceremony.'),('One satisfying checkmark','Finish it. Come back tomorrow with a little less to carry.')]))+section('Start for free.<br>Keep your options open.','<div class="offer-strip"><div class="offer-intro"><span class="pill">FREE CORE</span><p>Your tasks. Your agents. No subscription.</p><a class="button" href="/pricing.html">See how pricing works →</a></div><a href="/pricing.html" class="offer-option"><span>EVERYDAY TODOER</span><strong>Free</strong><p>Web · MCP · CLI · REST</p></a><a href="/pricing.html" class="offer-option"><span>OPTIONAL BUILT-IN AI</span><strong>Credits<small> planned</small></strong><p>Pay only when you ask for AI help.</p></a></div><p class="offer-footnote">AI credit sales and BYOK are planned · Pricing may evolve</p>')+section('A little more confidence<br>before you begin.',cards([('You can see the workflow','Explore concrete capture, planning and nested-task examples in our guides. No mystery about how you would use it.'),('AI stays optional','Use Todoer on its own. When you ask for built-in AI drafts, review them before applying.'),('Your work can travel','Export formats include text, CSV, JSON and ZIP. Keep your next move open.')]))+section('Good questions. Clear answers.',faq([('Can I manage tasks from Claude or ChatGPT?','Todoer provides MCP, REST and CLI access for compatible AI clients. You need an authorized connection. Specific hosted Claude and ChatGPT connector acceptance has not yet been verified; check client support before relying on it.'),('Do I have to build a productivity system first?','No. Start with an inbox and one list. Add sections, tags, nested tasks and a review routine only when they help.'),('Do I need AI credits for everyday tasks?','No. Core capture and planning do not need AI. Optional built-in AI usage would be purchased separately once credit sales are available.'),('Do I need a subscription?','No. Core task management and MCP, CLI and REST access are free. Optional built-in AI credits and bring-your-own-key support are planned; paid checkout is not open.')])) )
pages['product']=('Everything in its place.<br>You, back in motion.','A focused home for your tasks, project context and next actions.',section('Less searching. More starting.',cards(features))+section('From “I should” to “it’s done.”','<div class="journey"><article><span>01 / CAPTURE</span><h3>Start messy.</h3><p>Save the idea as it comes. Keep the link, original wording or rough brief alongside the task.</p></article><article><span>02 / CLARIFY</span><h3>Make it doable.</h3><p>Give a project its own list. Split tasks into steps, add notes and files, and keep the details close.</p></article><article><span>03 / FOLLOW THROUGH</span><h3>Come back with a plan.</h3><p>Use Today, Upcoming and recurring tasks to find your rhythm. Review your lists before the next week begins.</p></article></div><a class="button" href="/guides.html">Find a workflow that fits →</a>')+section('And when your ideas begin in chat?',agent_story()))
pages['agents']=('Don’t leave your next step<br>buried in a chat.','Connect the thinking you do with AI to the work you want to finish.',section('A useful conversation deserves a follow-through.',agent_story())+section('Three ways to put an agent to work.',cards([('“Capture this for later.”','Save action items into a list so they are waiting when you return to your day.'),('“What is already on my list?”','Let an authorized compatible agent search your tasks and retrieve relevant context.'),('“Help me break this down.”','Use optional built-in assistance to draft a task tree. Edit it, review it and apply it deliberately.')]))+section('Connect deliberately. Keep control.', '<ol class="steps"><li><b>Choose a compatible client.</b> Todoer supports MCP and offers REST and CLI surfaces. Verify the features your client can use.</li><li><b>Authorize the connection.</b> Use the supported account authorization or scoped credentials. Never paste credentials into a public chat.</li><li><b>Start with one small task.</b> Ask for a capture, check where it landed, and build from there.</li></ol><p>Claude and ChatGPT are examples of AI environments people may want to use. Their hosted Todoer connector acceptance remains unverified. This is not a claim of an official partnership or one-click integration.</p><p>Built-in assistance sends your submitted brief or capture and eligible destination context to configured providers. External agents follow their own provider policies.</p><a href="/privacy.html">Read how data is handled →</a>'))
# Public pricing contains only customer-facing offers; no internal cost assumptions.
core=pricing['core']; credits=pricing['ai_credits']; byok=pricing['byok']
tiles=f'<article class="plan featured"><span class="pill">START HERE</span><h2>{core["name"]}</h2><p class="price">Free</p><p>Capture, organize and finish your work.</p><ul class="plan-list">'+''.join(f'<li>{item}</li>' for item in core['includes'])+f'</ul>{cta}<p class="fine">Hosted registration depends on availability. No subscription required.</p></article>'
tiles+=f'<article class="plan"><span class="pill">PLANNED</span><h2>{credits["name"]}</h2><p class="price">Pay as you go</p><p>Prepaid credits for optional built-in AI assistance: task breakdown, classification and future AI reports.</p><ul class="plan-list"><li>Spend credits only when using built-in AI</li><li>No credits needed for core tasks or agent access</li><li>Pack prices will be published before sales</li></ul><p class="fine">Credit purchases, billing and spend overview are not available yet.</p></article>'
tiles+=f'<article class="plan"><span class="pill">PLANNED</span><h2>{byok["name"]}</h2><p class="price">Free<span> Todoer AI fee</span></p><p>Use your own provider key for built-in assistance.</p><ul class="plan-list"><li>You pay your AI provider directly</li><li>No Todoer AI usage fee</li><li>Your provider terms and limits apply</li></ul><p class="fine">Per-account BYOK is not available yet.</p></article>'
pages['pricing']=('Start for free.<br>AI on your terms.','Your tasks, web app and agent access are free. Optional built-in AI will use prepaid credits, or your own provider key.', '<section class="wrap pricing-content"><div class="grid md:grid-cols-3 gap-6">'+tiles+'</div><p class="pricing-note">'+pricing['pricing_policy']+'</p></section>'+section('Three ways to get things done.',cards([('Use Todoer on its own','Capture, lists, nested tasks, scheduling and review work without an AI provider.'),('Bring your agent','Connect a compatible AI agent using MCP, CLI or REST for free. Your agent or provider may charge separately.'),('Ask built-in AI for help','Prepaid credits and BYOK are planned. Current assistance depends on operator configuration; there is no paid checkout.')]))+section('Good questions. Clear answers.',faq([('Do external agents spend Todoer AI credits?','Core task operations through MCP, CLI and REST do not spend Todoer credits. Your external AI client handles its own provider usage. Optional built-in AI actions will require credits or a configured personal key once billing and BYOK ship.'),('Can I buy credits now?','No. Credit sales, Stripe billing and a spend overview are planned. Pack prices and purchase terms will be published before checkout opens.'),('Can I bring my own AI key?','Per-account BYOK is planned. You will pay your provider directly, with no Todoer AI usage fee. Today, built-in assistance is configured by the instance operator.'),('Will Todoer always have the same pricing?','Pricing may change as the service evolves. Published terms will explain any paid offer before purchase.')])) )
pages['about']=('A little more room<br>to be you.','Todoer exists to make the space between an idea and doing it feel smaller.', '<section class="wrap about-canvas"><div class="about-canvas-top"><span class="eyebrow">LESS TO CARRY</span><span class="canvas-caption">MORE TO LOOK FORWARD TO</span></div><div class="about-orbit"><div class="orbit-line orbit-one"></div><div class="orbit-line orbit-two"></div><span class="orbit-note note-one">That idea worth making.</span><span class="orbit-note note-two">The call you meant to make.</span><div class="orbit-center"><span class="orbit-check">✓</span><p>Life happens<br>outside the list.</p></div><span class="orbit-note note-three">An evening that’s yours.</span><span class="orbit-note note-four">One small step forward.</span></div><div class="about-canvas-bottom"><p>A place for your commitments.<br>More attention for everything else.</p><a href="/product.html">Find your next step →</a></div></section><section class="wrap about-story"><div><p class="eyebrow">WHY TODOER EXISTS</p><h2>Getting organized <br>should give you <br><span>something back.</span></h2></div><div class="about-story-copy"><p>Not another routine to maintain. Not a dashboard to keep perfect. Just a little less effort between knowing what matters and getting on with it.</p><p>Capture the thought. Keep the context. Ask AI for help when it’s useful. Then close the app and go do the thing.</p><div class="about-byline"><span>Independently made by <strong>Matteo Merola</strong></span><a href="mailto:info@todoer.pro">Say hello ↗</a></div></div></section>')

pages['contact']=('Let’s talk.','A question, an idea, or something we can help with?',section('One inbox. A real conversation.','<div class="contact-grid"><article class="card contact-email"><span class="number">EMAIL US</span><h3>We’re listening.</h3><a class="email-link" href="mailto:info@todoer.pro">info@todoer.pro ↗</a><p>Product questions, feedback, account help<br>and privacy requests.</p><a class="button" href="mailto:info@todoer.pro">Write to us ↗</a></article><article class="card contact-address"><span class="number">POSTAL ADDRESS</span><h3>Merola Software &amp; Services</h3><address>Wartauweg 19<br>8049 Zurich<br>Switzerland</address><p class="fine">Please keep passwords and access tokens private.</p></article></div>'))
# Stable legal sources are separate from generated layout; no repeated heading accumulation.
for key in ['terms','privacy','cookies','imprint']:
 title,desc,body=pages[key]
 content=old[key] if key in old else re.search(r'<section class="wrap block">(.*?)</section>',body,re.S).group(1)
 content=re.sub(r'^<h2>.*?</h2>','',content,count=1)
 links=[]
 def legal_heading(m):
  ident='legal-'+str(len(links)+1);links.append((ident,re.sub('<[^>]+>','',m.group(1))))
  return f'<h2 id="{ident}">{m.group(1)}</h2>'
 content=re.sub(r'<h2>(.*?)</h2>',legal_heading,content)
 toc=''.join(f'<a href="#{i}">{t}</a>' for i,t in links)
 pages[key]=( {'terms':'Clear terms. Shared expectations.','privacy':'Your work is personal.<br>Here’s how we handle it.','cookies':'Small files.<br>Clear explanations.','imprint':'The people behind the product.'}[key],desc,f'<section class="wrap legal-layout"><aside class="legal-sidebar"><p class="eyebrow">ON THIS PAGE</p><nav aria-label="Page contents">{toc}</nav><a href="/contact.html">Questions? Contact us →</a></aside><article class="legal-document"><p class="document-label">TODOER / {key.upper()}</p>{content}</article></section>')
